sp_p_18_6.primary_css_block:
.product-hero__props--primary {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.product-hero__props--primary .product-hero__prop {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  min-width: 0;
}

.product-hero__prop-icon {
  flex: 0 0 auto;
  width: 1.6em;
  height: 1.6em;
  display: flex;
  align-items: center;
  justify-content: center;
}

.product-hero__prop-icon svg {
  display: block;
  width: 1.6em;
  height: 1.6em;
}

.product-hero__prop-content {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

@media (max-width: 640px) {
  .product-hero__props--primary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

